const normalizeAuthor = (author?: string): string => {
    if (!author || author.trim() === '' || author === 'Belk Digital Team') {
        return DEFAULT_BLOG_AUTHOR;
    }
    return author;
};

export const getBlogPosts = (language: string): BlogPost[] => {
    let posts: BlogPost[];
    switch (language) {
        case 'es':
            posts = blogPostsES;
            break;
        case 'fr':
            posts = blogPostsFR;
            break;
        case 'de':
            posts = blogPostsDE;
            break;
        default:
            posts = blogPostsEN;
            break;
    }
    return posts.map(post => ({
        ...post,
        author: normalizeAuthor(post.author)
    }));
};

// Draft blog slugs configuration - all eight articles published
export const DRAFT_BLOG_SLUGS: ReadonlySet<string> = new Set([]);

export const isDraftSlug = (slug: string): boolean => DRAFT_BLOG_SLUGS.has(slug);

// Canonical priority mapping for same-date tie-breaking (newest batch to oldest)
const CANONICAL_SLUG_PRIORITY: ReadonlyMap<string, number> = new Map([
    ['why-website-visitors-abandon-forms', 0],
    ['ai-chatbots-business-websites', 1],
    ['email-lead-nurturing-b2b-qualified-opportunities', 2],
    ['marketing-platform-conversion-tracking-attribution-guide', 3],
    ['meta-ads-creative-fatigue-identify-refresh', 4],
    ['meta-partnership-ads-creator-content-testing', 5],
    ['b2b-lead-generation-peptide-suppliers', 6],
    ['can-peptide-suppliers-advertise-google-ads-meta', 7],
]);

export const sortBlogPostsChronologically = (posts: BlogPost[]): BlogPost[] => {
    const indexMap = new Map(posts.map((p, idx) => [p.slug, idx]));
    return [...posts].sort((a, b) => {
        const timeA = new Date(a.date).getTime() || 0;
        const timeB = new Date(b.date).getTime() || 0;
        if (timeB !== timeA) {
            return timeB - timeA;
        }
        const priorityA = CANONICAL_SLUG_PRIORITY.get(a.slug);
        const priorityB = CANONICAL_SLUG_PRIORITY.get(b.slug);
        if (priorityA !== undefined && priorityB !== undefined) {
            return priorityA - priorityB;
        }
        if (priorityA !== undefined) return -1;
        if (priorityB !== undefined) return 1;
        const idxA = indexMap.get(a.slug) ?? 0;
        const idxB = indexMap.get(b.slug) ?? 0;
        if (idxA !== idxB) {
            return idxA - idxB;
        }
        return a.slug.localeCompare(b.slug);
    });
};

export const getPublishedBlogPosts = (language: string): BlogPost[] => {
    return sortBlogPostsChronologically(getBlogPosts(language).filter(post => !isDraftSlug(post.slug)));
};
